# The intake dates in the catalogue are last cycle's, so the dashboard was
# telling a student their deadline was a month in the past. Intakes repeat
# annually, so a passed date is rolled forward to the next occurrence — which is
# what "winter closes 15 July" means. Fix the dates in the workbook and this
# becomes a no-op.
patch("dashboard.html", "deadlines roll forward to the next intake",
      "const dateOf = p => (p.intakes && p.intakes[0])\n"
      "  ? new Date(p.intakes[0].deadline).toLocaleDateString('en-GB',\n"
      "      {day:'numeric', month:'short', year:'numeric'}) : '';",
      "const dateOf = p => {\n"
      "  const now = new Date();\n"
      "  const ds = (p.intakes || []).map(i => {\n"
      "    const d = new Date(i.deadline);\n"
      "    if (isNaN(d)) return null;\n"
      "    while (d < now) d.setFullYear(d.getFullYear() + 1);\n"
      "    return d;\n"
      "  }).filter(Boolean).sort((a, b) => a - b);\n"
      "  return ds[0] ? ds[0].toLocaleDateString('en-GB',\n"
      "    {day:'numeric', month:'short', year:'numeric'}) : '';\n"
      "};")

# Sign-in was a form that wrote a name into localStorage and navigated. There was
# no account, no password check and nothing stopping anyone typing any email and
# landing in "their" dashboard. It now creates and authenticates a real account
# against the server, which sets an HttpOnly session cookie.
patch("login.html", "submit handler can await the server",
      "$('#authForm').addEventListener('submit', e => {",
      "$('#authForm').addEventListener('submit', async e => {")

patch(
    "login.html",
    "sign in and sign up against the real API",
    """  /* No auth yet, so the session is the name and email, kept locally. The
     dashboard reads it to greet the student and find their order.
     PROD: POST /api/session and let the server set an httpOnly cookie. */
  try {
    const paid = JSON.parse(localStorage.getItem('glovels_order') || '{}');
    localStorage.setItem('glovels_user', JSON.stringify({
      name: (signup && $('#lName') ? $('#lName').value.trim() : '')
            || paid.name
            || ($('#lEmail').value.trim().toLowerCase() === DEMO.email ? DEMO.name : ''),
      email: $('#lEmail').value.trim(),
      signedInAt: new Date().toISOString()
    }));
  } catch (err) { /* private browsing blocks storage; the dashboard copes */ }
  location.href = DEMO.dash;
});""",
    """  /* A real account on the server. The password is hashed with scrypt there and
     the session comes back as an HttpOnly cookie, so no script on this page —
     ours or anyone else's — can read it. */
  const btn = $('#submit-btn');
  const was = btn.textContent;
  btn.disabled = true;
  btn.textContent = signup ? 'Creating your account\\u2026' : 'Signing in\\u2026';
  showAuthError('');

  const payload = signup
    ? { name: $('#lName').value.trim(), email: $('#lEmail').value.trim(),
        phone: $('#lPhone') ? $('#lPhone').value.trim() : '', password: $('#lPass').value }
    : { email: $('#lEmail').value.trim(), password: $('#lPass').value };

  try {
    const r = await fetch(signup ? '/api/auth/signup' : '/api/auth/login', {
      method: 'POST',
      credentials: 'same-origin',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    const data = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(data.error || 'That did not work. Please try again.');

    /* An order paid for before signing up is claimed by this email at sign-up,
       so a student who paid as a guest does not land in an empty dashboard. */
    if (data.claimedOrders) {
      try { sessionStorage.setItem('glovels_claimed', String(data.claimedOrders)); } catch (e2) {}
    }
    const next = new URLSearchParams(location.search).get('next');
    location.href = (next && /^\\/[a-z0-9/_-]*$/i.test(next)) ? next : 'dashboard.html';
  } catch (err) {
    btn.disabled = false;
    btn.textContent = was;
    showAuthError(/Failed to fetch|NetworkError/i.test(err.message)
      ? 'The Glovels server is not running. Start it with start.command and try again.'
      : err.message);
  }
});

/* One place for what went wrong, under the button where the eye already is. */
function showAuthError(msg) {
  let el = document.getElementById('authErr');
  if (!el) {
    el = document.createElement('p');
    el.id = 'authErr';
    el.setAttribute('role', 'alert');
    el.style.cssText = 'margin:12px 0 0;padding:11px 13px;border-radius:10px;font:600 13px/1.5 '
      + 'system-ui,sans-serif;background:#fdf3f2;border:1px solid #f0c8c4;color:#7a2118;display:none';
    document.getElementById('submit-btn').insertAdjacentElement('afterend', el);
  }
  el.textContent = msg || '';
  el.style.display = msg ? 'block' : 'none';
}""",
    marker="showAuthError")   # later patches edit this block; test for this instead

# Coming from a checkout, the sign-up form opens with the paid email locked in,
# because an order filed under one address and an account created under a typo
# of it is a support ticket nobody can resolve from the outside.
patch("login.html", "arriving from checkout opens sign-up with that email",
      "switchTab('signin');\n\n/* ---- integration: validation, terms, and a session ---------------------- */",
      "switchTab('signin');\n\n/* Arriving from a checkout: open the sign-up tab with the email the order was\n   filed under already in the box, so the two cannot drift apart by a typo. */\n(function () {\n  const q = new URLSearchParams(location.search);\n  if (q.get('signup')) {\n    switchTab('signup');\n    const mail = q.get('email');\n    if (mail) {\n      const f = document.getElementById('lEmail');\n      f.value = mail;\n      f.readOnly = true;\n      f.style.background = '#f4f6f9';\n      f.title = 'This is the email your order is filed under.';\n      const note = document.createElement('p');\n      note.style.cssText = 'margin:12px 0 0;padding:11px 13px;border-radius:10px;font:600 12.8px/1.5 '\n        + 'system-ui,sans-serif;background:#eaf6ee;border:1px solid #bfe0cc;color:#14603a';\n      note.textContent = 'Your order is waiting on this address. Set a password and your '\n        + 'universities are in your dashboard straight away.';\n      document.getElementById('authForm').insertAdjacentElement('beforebegin', note);\n    }\n  }\n})();\n\n/* ---- integration: validation, terms, and a session ---------------------- */")

